function countOre(pat) { return sdk.getInventory().filter(i => pat.test(i.name)).reduce((a, i) => a + i.count, 0); }
const log = [];
const t0 = Date.now();
const end = Date.now() + 150000;
let fails = 0;
while (Date.now() < end) {
  const cu = countOre(/copper ore/i), tin = countOre(/tin ore/i);
  if (cu >= 12 && tin >= 12) break;
  const wantName = cu < tin ? /copper/i : /tin/i;
  const s = sdk.getState();
  const rocks = s.nearbyLocs.filter(l => /^rocks/i.test(l.name) && wantName.test(l.name))
    .filter(l => l.optionsWithIndex?.some(o => /^mine$/i.test(o.text)))
    .sort((a, b) => a.distance - b.distance);
  if (!rocks.length) { await sdk.waitForTicks(3); fails++; if (fails > 40) break; continue; }
  const before = cu + tin;
  const t1 = Date.now();
  const r = await bot.interactLoc(rocks[0], 'Mine');
  const ok = await sdk.waitForCondition(() => countOre(/ore/i) > before, 8000).then(() => true).catch(() => false);
  log.push(`${rocks[0].name} ${ok ? 'ok' : 'FAIL'} ${Date.now() - t1}ms`);
}
return { totalMs: Date.now() - t0, n: log.length, fails: log.filter(l => /FAIL/.test(l)).length, sample: log.slice(0, 5), inv: sdk.getInventory().map(i => `${i.name}`).join(','), mining: sdk.getSkill('Mining').level };

